pub fn WebSocket(comptime ssl_flag: i32) type {
        return struct {

pub fn raw(self: *@This()) *RawWebSocket {
            return bun.cast(*RawWebSocket, self);
    }

pub fn as(self: *@This(), comptime T: type) ?*T {
            return (blk: {
            break :blk @ptrCast(@alignCast(uws_ws_get_user_data(ssl_flag, self.raw())));

});
    }

pub fn close(self: *@This()) void {
            _ = uws_ws_close(ssl_flag, self.raw());
    }

pub fn send(self: *@This(), message: []const u8, opcode: bun.uws.Opcode) bun.uws.SendStatus {
            return uws_ws_send(ssl_flag, self.raw(), message.ptr, message.len, opcode);
    }

pub fn sendWithOptions(self: *@This(), message: []const u8, opcode: bun.uws.Opcode, compress: bool, fin: bool) bun.uws.SendStatus {
            return uws_ws_send_with_options(ssl_flag, self.raw(), message.ptr, message.len, opcode, compress, fin);
    }

pub fn memoryCost(self: *@This()) usize {
            return self.raw().memoryCost(ssl_flag);
    }

pub fn sendLastFragment(self: *@This(), message: []const u8, compress: bool) bun.uws.SendStatus {
            return uws_ws_send_last_fragment(ssl_flag, self.raw(), message.ptr, message.len, compress);
    }

pub fn end(self: *@This(), code: i32, message: []const u8) void {
            _ = uws_ws_end(ssl_flag, self.raw(), code, message.ptr, message.len);
    }

pub fn cork(self: *@This(), ctx: anytype, comptime callback: anytype) void {
            const Wrapper = struct {

pub fn wrap(user_data: ?*anyopaque) callconv(.c) void {
            {
                _ = callback(@ptrCast(@alignCast(user_data)));
            }
    }
};
            {
                _ = uws_ws_cork(ssl_flag, self.raw(), Wrapper.wrap, @ptrCast(ctx));
            }
    }

pub fn subscribe(self: *@This(), topic: []const u8) bool {
            return uws_ws_subscribe(ssl_flag, self.raw(), topic.ptr, topic.len);
    }

pub fn unsubscribe(self: *@This(), topic: []const u8) bool {
            return uws_ws_unsubscribe(ssl_flag, self.raw(), topic.ptr, topic.len);
    }

pub fn isSubscribed(self: *@This(), topic: []const u8) bool {
            return uws_ws_is_subscribed(ssl_flag, self.raw(), topic.ptr, topic.len);
    }

pub fn publish(self: *@This(), topic: []const u8, message: []const u8) bool {
            return uws_ws_publish(ssl_flag, self.raw(), topic.ptr, topic.len, message.ptr, message.len);
    }

pub fn publishWithOptions(self: *@This(), topic: []const u8, message: []const u8, opcode: bun.uws.Opcode, compress: bool) bool {
            return uws_ws_publish_with_options(ssl_flag, self.raw(), topic.ptr, topic.len, message.ptr, message.len, opcode, compress);
    }

pub fn getBufferedAmount(self: *@This()) u32 {
            return @intCast(uws_ws_get_buffered_amount(ssl_flag, self.raw()));
    }

pub fn getRemoteAddress(self: *@This(), buf: []u8) []u8 {
            var ptr: [*c]u8 = undefined;
            _ = &ptr;
            const len = uws_ws_get_remote_address(ssl_flag, self.raw(), (&ptr));
            {
                _ = bun.copy(u8, buf, ptr[0..len]);
            }
            return buf[0..len];
    }
};
}
